L["HUHURAN: Raserei sofort einlullen! Ab 30 % Burn!"] = "哈霍兰：狂乱立刻宁神！30%起爆发！"
L["Naturwiderstand nahe am Boss, Wyverngift gezielt bannen."] = "自然抗性贴近Boss，翼龙钉刺有针对地驱散。"
L["Zwillingsimperatoren: Vek'lor + Vek'nilash"] = "双子皇帝：维克洛尔大帝 + 维克尼拉斯大帝"
